Definition chn_0RB0LC_1LA1RB_0RD1LA_1LC1RD : list lstep := [SWin 1; SWinR 5; SCycL 2 0; SWin 4; SCycR 2; SWin 4].

Lemma run_inner_0RB0LC_1LA1RB_0RD1LA_1LC1RD : srun tm false true chn_0RB0LC_1LA1RB_0RD1LA_1LC1RD AI0_0RB0LC_1LA1RB_0RD1LA_1LC1RD = Some (AI1_0RB0LC_1LA1RB_0RD1LA_1LC1RD, 4, 14).
