(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LC_1LA1RB_0RD1LA_1LC1RD : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
