    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LA1RB_0RD1LA_1LC1RD [SWinR 2; SCycL 2 0; SWin 6; SCycR 2; SWin 2; SRotL 1; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LA1RB_0RD1LA_1LC1RD [SWinR 2; SCycL 2 0; SWin 6; SCycR 2; SWin 2] (StB, S1) ltac:(vm_compute; reflexivity)
