(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LC_1LA1RB_1LD1RC_0RC0LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A0_0RB0LC_1LA1RB_1LD1RC_0RC0LA.
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (H1 & _).
  unfold Cc_0RB0LC_1LA1RB_1LD1RC_0RC0LA, cden, A0_0RB0LC_1LA1RB_1LD1RC_0RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB0LC_1LA1RB_1LD1RC_0RC0LA : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_0RB0LC_1LA1RB_1LD1RC_0RC0LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p j q0 E) as (_ & H2).
  unfold Cc_0RB0LC_1LA1RB_1LD1RC_0RC0LA, cden, A1_0RB0LC_1LA1RB_1LD1RC_0RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LC_1LA1RB_1LD1RC_0RC0LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (6 * j + 10), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_0RB0LC_1LA1RB_1LD1RC_0RC0LA).
  split; [lia|]. split; [| exact (gei_0RB0LC_1LA1RB_1LD1RC_0RC0LA p j q0 E)].
  rewrite (gsi_0RB0LC_1LA1RB_1LD1RC_0RC0LA p j q0 E).
  exact (srun_sound tm false true chi_0RB0LC_1LA1RB_1LD1RC_0RC0LA A0_0RB0LC_1LA1RB_1LD1RC_0RC0LA A1_0RB0LC_1LA1RB_1LD1RC_0RC0LA 6 10
           run_int_0RB0LC_1LA1RB_1LD1RC_0RC0LA (Ap_Alph_10_11_11 q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB0LC_1LA1RB_1LD1RC_0RC0LA : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LC_1LA1RB_1LD1RC_0RC0LA.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_0RB0LC_1LA1RB_1LD1RC_0RC0LA, cden, B0_0RB0LC_1LA1RB_1LD1RC_0RC0LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
