(** ** The lap *)

Lemma lap_0RB0LC_1LA1RB_1RD1RD_1LD0LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
