  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StD
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S0 DL StC
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DR StB end.

(** Its mirror 0LB0RC_1RC0LD_1RA0RC_0RA1LB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC0RD_1LA0LC_0LA1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S0 DR StC
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC0RD_1LA0LC_0LA1RB : list Instr := [].
Definition tmw_0RB0LC_1LC0RD_1LA0LC_0LA1RB : TM := tm_wrap_trs tmm_0RB0LC_1LC0RD_1LA0LC_0LA1RB pins_0RB0LC_1LC0RD_1LA0LC_0LA1RB.
