Lemma lapi_0RB0LC_1LC0RD_1LA0LC_0LA1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
