Lemma geo_0RB0LC_1LC0RD_1LA0LC_0LA1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_1LC0RD_1LA0LC_0LA1RB) = lift (Cc (Pos.succ p)).
