    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S0;S1], S0, []))).
  { unfold Cin_0RB0LC_1LC0RD_1LA0LC_0LA1RB. rewrite epow2_0RB0LC_1LC0RD_1LA0LC_0LA1RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
