  { unfold cden, BM1_0RB0LC_1LC0RD_1LA0LC_0LA1RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin2 (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1;S1], S0, []))).
  { unfold Cin2_0RB0LC_1LC0RD_1LA0LC_0LA1RB. rewrite epow22_0RB0LC_1LC0RD_1LA0LC_0LA1RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LC_1LC0RD_1LA0LC_0LA1RB. rewrite ?lift_app_blank. reflexivity.
