Lemma fireo_0RB0LC_1LC0RD_1LA0LC_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1LC0RD_1LA0LC_1LC1RB = Some t ->
