    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC0RD_1LA0LC_1LC1RB p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by the boot, the chained counts, and that prefix. *)
Lemma firex_0RB0LC_1LC0RD_1LA0LC_1LC1RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LC_1LC0RD_1LA0LC_1LC1RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  assert (HB1 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin (pow2 j))).
  { exists (4 * j + 6), (cden [] [] j BB1_0RB0LC_1LC0RD_1LA0LC_1LC1RB).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC0RD_1LA0LC_1LC1RB j)].
    rewrite (gso_0RB0LC_1LC0RD_1LA0LC_1LC1RB p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC0RD_1LA0LC_1LC1RB B0_0RB0LC_1LC0RD_1LA0LC_1LC1RB BB1_0RB0LC_1LC0RD_1LA0LC_1LC1RB 4 6
             run_boot_0RB0LC_1LC0RD_1LA0LC_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  assert (HB2 : exists n c, 0 < n /\ csteps tm n (Cc p) = Some c
                /\ lift c = lift (Cin2 (pow2 j))).
  { apply (boot_via_fill tm Cc Cin Cin2 lapin_0RB0LC_1LC0RD_1LA0LC_1LC1RB p (pow2 j) (pow2 j));
      [exact HB1|].
    exists (4 * j + 4), (cden [] [] j BM1_0RB0LC_1LC0RD_1LA0LC_1LC1RB).
    split; [| exact (gbo2_0RB0LC_1LC0RD_1LA0LC_1LC1RB j)].
    rewrite (gxi_0RB0LC_1LC0RD_1LA0LC_1LC1RB j).
    exact (srun_sound tm true true chm_0RB0LC_1LC0RD_1LA0LC_1LC1RB BM0_0RB0LC_1LC0RD_1LA0LC_1LC1RB BM1_0RB0LC_1LC0RD_1LA0LC_1LC1RB 4 4
             run_shift_0RB0LC_1LC0RD_1LA0LC_1LC1RB [] [] j ltac:(reflexivity) ltac:(reflexivity)). }
  destruct HB2 as (nB & cB & _ & HcB & HlB).
  apply (fire_via_fill tm Cc Cin2 lapin2_0RB0LC_1LC0RD_1LA0LC_1LC1RB t p (pow2 j));
    [exists nB, cB; exact (conj HcB HlB)|].
  apply (fire_lift_of_csteps tm (fun _ : positive => Cin2 (fill (pow2 j))) xH).
  apply (fire_of_run_instr tm (fun _ : positive => Cin2 (fill (pow2 j)))
                    true true l BE0_0RB0LC_1LC0RD_1LA0LC_1LC1RB xH j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gxi2_0RB0LC_1LC0RD_1LA0LC_1LC1RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LC0RD_1LA0LC_1LC1RB : forall t, ~ In t pins_0RB0LC_1LC0RD_1LA0LC_1LC1RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1LC0RD_1LA0LC_1LC1RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LC_1LC0RD_1LA0LC_1LC1RB
      with (l := []).
    vm_compute; reflexivity.
