Definition Cc_0RB0LC_1LC0RD_1LA1LC_1LC1RB (p : positive) : cconf := (StA, (Ap_Alph_10_11_11 p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB0LC_1LC0RD_1LA1LC_1LC1RB.

(** ** The certificate *)

Definition A0_0RB0LC_1LC0RD_1LA1LC_1LC1RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
