Definition chi_0RB0LC_1LC0RD_1LA1LC_1LC1RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_int_0RB0LC_1LC0RD_1LA1LC_1LC1RB : srun tm false true chi_0RB0LC_1LC0RD_1LA1LC_1LC1RB A0_0RB0LC_1LC0RD_1LA1LC_1LC1RB = Some (A1_0RB0LC_1LC0RD_1LA1LC_1LC1RB, 4, 4).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB0LC_1LC0RD_1LA1LC_1LC1RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB0LC_1LC0RD_1LA1LC_1LC1RB : sconf := mkC StA (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
