(** ** The lap *)

Lemma lap_0RB0LC_1LC1RA_0LD1LC_0RD1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RA_0LD1LC_0RD1RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LC_1LC1RA_0LD1LC_0RD1RB B0_0RB0LC_1LC1RA_0LD1LC_0RD1RB B1_0RB0LC_1LC1RA_0LD1LC_0RD1RB 6 26 p j' [] []).
    + exact run_ovf_0RB0LC_1LC1RA_0LD1LC_0RD1RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LC_1LC1RA_0LD1LC_0RD1RB p j' E).
    + exact (geo_0RB0LC_1LC1RA_0LD1LC_0RD1RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1LC1RA_0LD1LC_0RD1RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 17.
  assert (H : match csteps tm 17 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 17 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

