Lemma lapi_0RB0LC_1LC1RB_0LD1LA_0RA___ : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
