(** The chain into this family lands on its anchor up to 0/2
    trailing blanks. *)
Lemma gbo_0RB0LC_1LC1RB_0LD1LA_0RA___ : forall j, lift (cden [] [] j BB1_0RB0LC_1LC1RB_0LD1LA_0RA___) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_0LD1LA_0RA___ = (StB, (rep [S1;S0] j ++ [S1;S1], S0, (([]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_0RB0LC_1LC1RB_0LD1LA_0RA___, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB0LC_1LC1RB_0LD1LA_0RA___. rewrite epow2_0RB0LC_1LC1RB_0LD1LA_0RA___.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LC_1LC1RB_0LD1LA_0RA___. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LC_1LC1RB_0LD1LA_0RA___ : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LC_1LC1RB_0LD1LA_0RA___.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_0LD1LA_0RA___, cden, BE0_0RB0LC_1LC1RB_0LD1LA_0RA___; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_1LC1RB_0LD1LA_0RA___ : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0LC_1LC1RB_0LD1LA_0RA___ p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_1LC1RB_0LD1LA_0RA___ : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_0LD1LA_0RA___ p (pow2 j)).
  - exists (4 * j + 9), (cden [] [] j BB1_0RB0LC_1LC1RB_0LD1LA_0RA___).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_0LD1LA_0RA___ j)].
    rewrite (gso_0RB0LC_1LC1RB_0LD1LA_0RA___ p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_0LD1LA_0RA___ B0_0RB0LC_1LC1RB_0LD1LA_0RA___ BB1_0RB0LC_1LC1RB_0LD1LA_0RA___ 4 9
             run_boot_0RB0LC_1LC1RB_0LD1LA_0RA___ [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 11), (cden [] [] j B1_0RB0LC_1LC1RB_0LD1LA_0RA___).
    split; [| exact (geo_0RB0LC_1LC1RB_0LD1LA_0RA___ p j E)].
    rewrite (gxi_0RB0LC_1LC1RB_0LD1LA_0RA___ j).
    exact (srun_sound tm true true che_0RB0LC_1LC1RB_0LD1LA_0RA___ BE0_0RB0LC_1LC1RB_0LD1LA_0RA___ B1_0RB0LC_1LC1RB_0LD1LA_0RA___ 4 11
             run_exit_0RB0LC_1LC1RB_0LD1LA_0RA___ [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_0LD1LA_0RA___ : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_0LD1LA_0RA___ p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1LC1RB_0LD1LA_0RA___ p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1LC1RB_0LD1LA_0RA___ : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 8.
  assert (H : match csteps tm 8 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 8 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
