Definition mk_0RB0LC_1LC1RB_0LD1LA_1RC0RA (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB0LC_1LC1RB_0LD1LA_1RC0RA.

(** 0RB0LC_1LC1RB_0LD1LA_1RC0RA *)
(** 0RB0LC_1LC1RB_0LD1LA_1RC0RA -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LC_1LC1RB_0LD1LA_1RC0RA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DR StC | StD, S1 => mk S0 DR StA end.

(** Its mirror 0LB0RC_1RC1LB_0RD1RA_1LC0LA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC1RB_0LD1LA_1RC0RA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DL StC | StD, S1 => mk S0 DL StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC1RB_0LD1LA_1RC0RA : list Instr := [].
Definition tmw_0RB0LC_1LC1RB_0LD1LA_1RC0RA : TM := tm_wrap_trs tmm_0RB0LC_1LC1RB_0LD1LA_1RC0RA pins_0RB0LC_1LC1RB_0LD1LA_1RC0RA.
Local Notation tm := tmw_0RB0LC_1LC1RB_0LD1LA_1RC0RA.

Lemma mirror_ok_0RB0LC_1LC1RB_0LD1LA_1RC0RA : mirror_tm tm_0RB0LC_1LC1RB_0LD1LA_1RC0RA = tmm_0RB0LC_1LC1RB_0LD1LA_1RC0RA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

