  | StD, S0 => mk S0 DL StC | StD, S1 => mk S1 DL StA end.

(** Its mirror 0LB0RC_1RC1LB_0LB1RD_0RC1RA: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC1RB_0RB1LD_0LC1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StB | StC, S1 => mk S1 DR StD
  | StD, S0 => mk S0 DR StC | StD, S1 => mk S1 DR StA end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC1RB_0RB1LD_0LC1LA : list Instr := [].
Definition tmw_0RB0LC_1LC1RB_0RB1LD_0LC1LA : TM := tm_wrap_trs tmm_0RB0LC_1LC1RB_0RB1LD_0LC1LA pins_0RB0LC_1LC1RB_0RB1LD_0LC1LA.
Local Notation tm := tmw_0RB0LC_1LC1RB_0RB1LD_0LC1LA.

Lemma mirror_ok_0RB0LC_1LC1RB_0RB1LD_0LC1LA : mirror_tm tm_0RB0LC_1LC1RB_0RB1LD_0LC1LA = tmm_0RB0LC_1LC1RB_0RB1LD_0LC1LA.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB0LC_1LC1RB_0RB1LD_0LC1LA (p : positive) : cconf := (StB, (Ap_Alph_110_111_111 p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB0LC_1LC1RB_0RB1LD_0LC1LA.

(** ** The certificate *)

Definition A0_0RB0LC_1LC1RB_0RB1LD_0LC1LA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition A1_0RB0LC_1LC1RB_0RB1LD_0LC1LA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chi_0RB0LC_1LC1RB_0RB1LD_0LC1LA : list lstep := [SWinR 2; SCycL 3 0; SWin 6; SCycR 3; SWin 2].

Lemma run_int_0RB0LC_1LC1RB_0RB1LD_0LC1LA : srun tm false true chi_0RB0LC_1LC1RB_0RB1LD_0LC1LA A0_0RB0LC_1LC1RB_0RB1LD_0LC1LA = Some (A1_0RB0LC_1LC1RB_0RB1LD_0LC1LA, 6, 10).
