Definition B0_0RB0LC_1LC1RB_0RB1LD_0LC1LA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB0LC_1LC1RB_0RB1LD_0LC1LA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 1 [S1;S1;S1]) S0 (mkS [S0] [] 0 0 []).
(** ** The INNER anchor family -- Ap_Alph_110_111_1 at StB *)
Definition Cin_0RB0LC_1LC1RB_0RB1LD_0LC1LA (v : positive) : cconf := (StB, (Ap_Alph_110_111_1 v ++ [S1;S1], S0, [S1;S1])).
