(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB0LC_1LC1RB_0RB1LD_0LC1LA : forall n, Ap_Alph_110_111_1 (pow2 n) = rep [S1;S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0LC_1LC1RB_0RB1LD_0LC1LA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [S1;S1] [] 0 0 []).
Definition AI1_0RB0LC_1LC1RB_0RB1LD_0LC1LA : sconf := mkC StB (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [S1;S1;S0] [] 0 0 []).
Definition chn_0RB0LC_1LC1RB_0RB1LD_0LC1LA : list lstep := [SWin 2; SWinR 4; SCycL 3 0; SWin 6; SCycR 3; SWin 6].

Lemma run_inner_0RB0LC_1LC1RB_0RB1LD_0LC1LA : srun tm false true chn_0RB0LC_1LC1RB_0RB1LD_0LC1LA AI0_0RB0LC_1LC1RB_0RB1LD_0LC1LA = Some (AI1_0RB0LC_1LC1RB_0RB1LD_0LC1LA, 6, 18).
