(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LC_1LC1RB_0RB1LD_0LC1LA : sconf := mkC StB (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [S1;S1] [] 0 0 []).
Definition che_0RB0LC_1LC1RB_0RB1LD_0LC1LA : list lstep := [SWin 2; SWinR 4; SCycL 3 0; SWin 3; SWinL 5; SCycR 3; SWin 4; SRotL 1; SFoldL 1].

