Lemma gen_0RB0LC_1LC1RB_0RB1LD_0LC1LA : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i AI1_0RB0LC_1LC1RB_0RB1LD_0LC1LA) = lift (Cin (Pos.succ v)).
