  exact (srun_sound tm false true chn_0RB0LC_1LC1RB_0RB1LD_0LC1LA AI0_0RB0LC_1LC1RB_0RB1LD_0LC1LA AI1_0RB0LC_1LC1RB_0RB1LD_0LC1LA 6 18
           run_inner_0RB0LC_1LC1RB_0RB1LD_0LC1LA (Ap_Alph_110_111_1 q0 ++ [S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_0RB0LC_1LC1RB_0RB1LD_0LC1LA : forall j, lift (cden [] [] j BB1_0RB0LC_1LC1RB_0RB1LD_0LC1LA) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_0RB1LD_0LC1LA = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, ([S1;S1]) ++ [S0]))).
  { unfold cden, BB1_0RB0LC_1LC1RB_0RB1LD_0LC1LA, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S1;S0] j ++ [S1;S1;S1], S0, [S1;S1]))).
  { unfold Cin_0RB0LC_1LC1RB_0RB1LD_0LC1LA. rewrite epow2_0RB0LC_1LC1RB_0RB1LD_0LC1LA.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LC_1LC1RB_0RB1LD_0LC1LA. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LC_1LC1RB_0RB1LD_0LC1LA : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LC_1LC1RB_0RB1LD_0LC1LA.
Proof.
  intro j.
  destruct (Alph_110_111_1.cview_none_Alph_110_111_1 (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_0RB1LD_0LC1LA, cden, BE0_0RB0LC_1LC1RB_0RB1LD_0LC1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_1LC1RB_0RB1LD_0LC1LA : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB0LC_1LC1RB_0RB1LD_0LC1LA. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_1LC1RB_0RB1LD_0LC1LA : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_0RB1LD_0LC1LA p (pow2 j)).
  - exists (6 * j + 17), (cden [] [] j BB1_0RB0LC_1LC1RB_0RB1LD_0LC1LA).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_0RB1LD_0LC1LA j)].
    rewrite (gso_0RB0LC_1LC1RB_0RB1LD_0LC1LA p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_0RB1LD_0LC1LA B0_0RB0LC_1LC1RB_0RB1LD_0LC1LA BB1_0RB0LC_1LC1RB_0RB1LD_0LC1LA 6 17
             run_boot_0RB0LC_1LC1RB_0RB1LD_0LC1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (6 * j + 18), (cden [] [] j B1_0RB0LC_1LC1RB_0RB1LD_0LC1LA).
    split; [| exact (geo_0RB0LC_1LC1RB_0RB1LD_0LC1LA p j E)].
    rewrite (gxi_0RB0LC_1LC1RB_0RB1LD_0LC1LA j).
    exact (srun_sound tm true true che_0RB0LC_1LC1RB_0RB1LD_0LC1LA BE0_0RB0LC_1LC1RB_0RB1LD_0LC1LA B1_0RB0LC_1LC1RB_0RB1LD_0LC1LA 6 18
             run_exit_0RB0LC_1LC1RB_0RB1LD_0LC1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_0RB1LD_0LC1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_0RB1LD_0LC1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1LC1RB_0RB1LD_0LC1LA p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1LC1RB_0RB1LD_0LC1LA : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 18.
  assert (H : match csteps tm 18 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 18 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1LC1RB_0RB1LD_0LC1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1LC1RB_0RB1LD_0LC1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_0RB1LD_0LC1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_0RB1LD_0LC1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
