Lemma fire_0RB0LC_1LC1RB_0RB1LD_0RB1LA : forall t, ~ In t pins_0RB0LC_1LC1RB_0RB1LD_0RB1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
