Lemma gz_0RB0LC_1LC1RB_0RB1LD_0RD1LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB0LC_1LC1RB_0RB1LD_0RD1LA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB0LC_1LC1RB_0RB1LD_0RD1LA = Cc (Pos.succ p).
