  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB0LC_1LC1RB_0RB1LD_1LA0RC p q0 E) as (HA & HB).
    exists (0 * 0 + 2). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB0LC_1LC1RB_0RB1LD_1LA0RC Z0_0RB0LC_1LC1RB_0RB1LD_1LA0RC Z1_0RB0LC_1LC1RB_0RB1LD_1LA0RC 0 2
               run_z_0RB0LC_1LC1RB_0RB1LD_1LA0RC (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0
