    exists (8 * j' + 10). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB0LC_1LC1RB_0RB1LD_1LA0RC P0_0RB0LC_1LC1RB_0RB1LD_1LA0RC P1_0RB0LC_1LC1RB_0RB1LD_1LA0RC 8 10
               run_p_0RB0LC_1LC1RB_0RB1LD_1LA0RC (Ap_Alph_011_111_1 q0 ++ [S0]) [] j'
