(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_1LC1RB_0RB1LD_1LA0RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0LC_1LC1RB_0RB1LD_1LA0RC p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_1LC1RB_0RB1LD_1LA0RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_0RB1LD_1LA0RC p (pow2 j)).
  - exists (8 * j + 4), (cden [] [] j BB1_0RB0LC_1LC1RB_0RB1LD_1LA0RC).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_0RB1LD_1LA0RC j)].
    rewrite (gso_0RB0LC_1LC1RB_0RB1LD_1LA0RC p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_0RB1LD_1LA0RC B0_0RB0LC_1LC1RB_0RB1LD_1LA0RC BB1_0RB0LC_1LC1RB_0RB1LD_1LA0RC 8 4
             run_boot_0RB0LC_1LC1RB_0RB1LD_1LA0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 11), (cden [] [] j B1_0RB0LC_1LC1RB_0RB1LD_1LA0RC).
    split; [| exact (geo_0RB0LC_1LC1RB_0RB1LD_1LA0RC p j E)].
    rewrite (gxi_0RB0LC_1LC1RB_0RB1LD_1LA0RC j).
    exact (srun_sound tm true true che_0RB0LC_1LC1RB_0RB1LD_1LA0RC BE0_0RB0LC_1LC1RB_0RB1LD_1LA0RC B1_0RB0LC_1LC1RB_0RB1LD_1LA0RC 8 11
             run_exit_0RB0LC_1LC1RB_0RB1LD_1LA0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_0RB1LD_1LA0RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_0RB1LD_1LA0RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1LC1RB_0RB1LD_1LA0RC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1LC1RB_0RB1LD_1LA0RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 2.
  assert (H : match csteps tm 2 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 2 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1LC1RB_0RB1LD_1LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1LC1RB_0RB1LD_1LA0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_0RB1LD_1LA0RC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_0RB1LD_1LA0RC p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LC_1LC1RB_0RB1LD_1LA0RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LC_1LC1RB_0RB1LD_1LA0RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LC_1LC1RB_0RB1LD_1LA0RC t p (pow2 j)).
  - exists (8 * j + 4), (cden [] [] j BB1_0RB0LC_1LC1RB_0RB1LD_1LA0RC). split;
      [| exact (gbo_0RB0LC_1LC1RB_0RB1LD_1LA0RC j)].
    rewrite (gso_0RB0LC_1LC1RB_0RB1LD_1LA0RC p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_0RB1LD_1LA0RC B0_0RB0LC_1LC1RB_0RB1LD_1LA0RC BB1_0RB0LC_1LC1RB_0RB1LD_1LA0RC 8 4
             run_boot_0RB0LC_1LC1RB_0RB1LD_1LA0RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LC_1LC1RB_0RB1LD_1LA0RC xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LC_1LC1RB_0RB1LD_1LA0RC j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LC1RB_0RB1LD_1LA0RC : forall t, ~ In t pins_0RB0LC_1LC1RB_0RB1LD_1LA0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1LC1RB_0RB1LD_1LA0RC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_0RB0LC_1LC1RB_0RB1LD_1LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 5; SWin 1; SUnrotL 1; SWinR 1]).
    vm_compute; reflexivity.
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LC_1LC1RB_0RB1LD_1LA0RC (StA, S1)).
    intros p1 j1 E1.
    exact (firex_0RB0LC_1LC1RB_0RB1LD_1LA0RC [SWinR 2; SCycL 3 0; SWin 2; SWinL 6] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_0RB0LC_1LC1RB_0RB1LD_1LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_0RB0LC_1LC1RB_0RB1LD_1LA0RC
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_0RB0LC_1LC1RB_0RB1LD_1LA0RC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_0RB0LC_1LC1RB_0RB1LD_1LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_0RB0LC_1LC1RB_0RB1LD_1LA0RC
      with (l := [SRotL 1; SWin 1; SCycL 3 0; SWin 2; SCycR 5; SWin 1]).
    vm_compute; reflexivity.
  - (* D1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LC_1LC1RB_0RB1LD_1LA0RC (StD, S1)).
    intros p1 j1 E1.
    exact (firex_0RB0LC_1LC1RB_0RB1LD_1LA0RC [SWinR 2; SCycL 3 0; SWin 2; SWinL 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem nqhtrm_0RB0LC_1LC1RB_0RB1LD_1LA0RC : NeverQuasiHaltsTr tmm_0RB0LC_1LC1RB_0RB1LD_1LA0RC.
Proof.
  apply (glue_neverqhtr tmm_0RB0LC_1LC1RB_0RB1LD_1LA0RC pins_0RB0LC_1LC1RB_0RB1LD_1LA0RC Cc 1).
  - exact boot_0RB0LC_1LC1RB_0RB1LD_1LA0RC.
  - intros p _. apply lap_0RB0LC_1LC1RB_0RB1LD_1LA0RC.
  - intros t Ht p _. apply fire_0RB0LC_1LC1RB_0RB1LD_1LA0RC. exact Ht.
Qed.

Theorem nqhtr_0RB0LC_1LC1RB_0RB1LD_1LA0RC : NeverQuasiHaltsTr tm_0RB0LC_1LC1RB_0RB1LD_1LA0RC.
Proof. apply (neverqhtr_mirror tm_0RB0LC_1LC1RB_0RB1LD_1LA0RC). rewrite mirror_ok_0RB0LC_1LC1RB_0RB1LD_1LA0RC. exact nqhtrm_0RB0LC_1LC1RB_0RB1LD_1LA0RC. Qed.

Theorem nonhalt_0RB0LC_1LC1RB_0RB1LD_1LA0RC : NonHalt tm_0RB0LC_1LC1RB_0RB1LD_1LA0RC.
Proof. apply never_qh_tr_nonhalt, nqhtr_0RB0LC_1LC1RB_0RB1LD_1LA0RC. Qed.

End LAPT_0RB0LC_1LC1RB_0RB1LD_1LA0RC.

Module LAPT_0RB0LC_1LC1RB_0RB1LD_1LA1LA.
(** * LAPT_0RB0LC_1LC1RB_0RB1LD_1LA1LA: TRANSITION-LEVEL board for machine 0RB0LC_1LC1RB_0RB1LD_1LA1LA, boarded by CERTIFICATE.

    Auto-emitted by tools/counters/emit_lapcert.py (UNTRUSTED emitter; the Coq
    kernel re-runs the checker on every line below).  Left-growth binary
    counter under the Ap_Alph_011_111_1 digit alphabet (Alph_011_111_1.v), anchored at

      Cc p = (StC, (Ap_Alph_011_111_1 p ++ [S0], S0, []))

    The lap is DATA, not a proof script: each branch is a list of steps for
    [Checkers/LapDecider.v], run by the kernel through [vm_compute] and
    discharged by the single theorem [srun_sound].

      interior  (cview p = (j, Some q0)):  j=0: 2 ; j=S j': 6*j'+8 steps
      overflow  (cview p = (S j, None)):   boot 6*j+5, then the inner counter's own laps to the
                                           all-ones fill, then exit 6*j+8

    The interior branch closes EXACTLY (which is what feeds
    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 192 interior anchors (interior); 6 overflow phases, j = 2..7 (246 inner laps) (nested overflow).
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
