(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB0LC_1LC1RB_0RB1LD_1LA1LA : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z0_0RB0LC_1LC1RB_0RB1LD_1LA1LA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] 0 Z1_0RB0LC_1LC1RB_0RB1LD_1LA1LA = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB0LC_1LC1RB_0RB1LD_1LA1LA, cden, Z0_0RB0LC_1LC1RB_0RB1LD_1LA1LA, Z1_0RB0LC_1LC1RB_0RB1LD_1LA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB0LC_1LC1RB_0RB1LD_1LA1LA : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P0_0RB0LC_1LC1RB_0RB1LD_1LA1LA /\
  cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j P1_0RB0LC_1LC1RB_0RB1LD_1LA1LA = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB0LC_1LC1RB_0RB1LD_1LA1LA, cden, P0_0RB0LC_1LC1RB_0RB1LD_1LA1LA, P1_0RB0LC_1LC1RB_0RB1LD_1LA1LA; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
