Lemma repmul_0RB0LC_1LC1RB_0RD0LA_1RD1LA : forall (u : list Sym) m i, rep u (m * i) = rep (rep u m) i.
Proof.
  intros u m i. induction i as [|i IH]; [rewrite Nat.mul_0_r; reflexivity|].
  replace (m * S i) with (m + m * i) by lia. rewrite rep_add, IH. reflexivity.
Qed.

Lemma repm_0RB0LC_1LC1RB_0RD0LA_1RD1LA : forall (u : list Sym) m i c1 c2,
