  assert (HC : Cin (pow2 j) = (StD, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB0LC_1LC1RB_0RD1LA_1LC1LA. rewrite epow2_0RB0LC_1LC1RB_0RD1LA_1LC1LA.
