    [LapCertGlue.reach_ovf]); the overflow branch closes one blank short of
    the anchor tail, hence up to [lift].

    Differentially validated against the raw simulator on BOTH branches --
    step counts AND exact configurations -- for 192 interior anchors (interior); 6 overflow phases, j = 2..7 (492 inner laps, 2 counts each) (nested overflow).
    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter Alph_10_11_11 LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift NestedLap2 ILCounter.
Import TNF_QH.
Import LapDecider.
Import BBBT4_Statement.
Import WrapTr.
Import AnchorVisitsTr.
Import LapGlueTr.
Import TNF_QHTr.
Import ListNotations.

Definition mk_0RB0LC_1LC1RB_0RD1LA_1RD1RB (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB0LC_1LC1RB_0RD1LA_1RD1RB.

(** 0RB0LC_1LC1RB_0RD1LA_1RD1RB *)
(** 0RB0LC_1LC1RB_0RD1LA_1RD1RB -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LC_1LC1RB_0RD1LA_1RD1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S1 DR StD | StD, S1 => mk S1 DR StB end.

(** Its mirror 0LB0RC_1RC1LB_0LD1RA_1LD1LB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC1RB_0RD1LA_1RD1RB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S0 DL StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S1 DL StD | StD, S1 => mk S1 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC1RB_0RD1LA_1RD1RB : list Instr := [].
Definition tmw_0RB0LC_1LC1RB_0RD1LA_1RD1RB : TM := tm_wrap_trs tmm_0RB0LC_1LC1RB_0RD1LA_1RD1RB pins_0RB0LC_1LC1RB_0RD1LA_1RD1RB.
Local Notation tm := tmw_0RB0LC_1LC1RB_0RD1LA_1RD1RB.

Lemma mirror_ok_0RB0LC_1LC1RB_0RD1LA_1RD1RB : mirror_tm tm_0RB0LC_1LC1RB_0RD1LA_1RD1RB = tmm_0RB0LC_1LC1RB_0RD1LA_1RD1RB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB0LC_1LC1RB_0RD1LA_1RD1RB (p : positive) : cconf := (StD, (Ap_Alph_10_11_11 p ++ [S0], S0, [])).
