Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_0RB0LC_1LC1RB_0RD1LA_1RD1RB /\
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_0RB0LC_1LC1RB_0RD1LA_1RD1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB0LC_1LC1RB_0RD1LA_1RD1RB, cden, Z0_0RB0LC_1LC1RB_0RD1LA_1RD1RB, Z1_0RB0LC_1LC1RB_0RD1LA_1RD1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_0RB0LC_1LC1RB_0RD1LA_1RD1RB /\
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_0RB0LC_1LC1RB_0RD1LA_1RD1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB0LC_1LC1RB_0RD1LA_1RD1RB, cden, P0_0RB0LC_1LC1RB_0RD1LA_1RD1RB, P1_0RB0LC_1LC1RB_0RD1LA_1RD1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - cbn [rep app Nat.mul Nat.add]; rewrite ?app_nil_r.
    change ([S0]) with (([]) ++ [S0]).
    rewrite !lift_app_blank.
    rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB0LC_1LC1RB_0RD1LA_1RD1RB p q0 E) as (HA & HB).
    exists (0 * 0 + 6), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_0RB0LC_1LC1RB_0RD1LA_1RD1RB).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chz_0RB0LC_1LC1RB_0RD1LA_1RD1RB Z0_0RB0LC_1LC1RB_0RD1LA_1RD1RB Z1_0RB0LC_1LC1RB_0RD1LA_1RD1RB 0 6
             run_z_0RB0LC_1LC1RB_0RD1LA_1RD1RB (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
             ltac:(discriminate) ltac:(reflexivity)).
  - destruct (gp_0RB0LC_1LC1RB_0RD1LA_1RD1RB p j' q0 E) as (HA & HB).
    exists (4 * j' + 10), (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j' P1_0RB0LC_1LC1RB_0RD1LA_1RD1RB).
    split; [lia|]. split; [| exact HB].
    rewrite HA.
    exact (srun_sound tm false true chp_0RB0LC_1LC1RB_0RD1LA_1RD1RB P0_0RB0LC_1LC1RB_0RD1LA_1RD1RB P1_0RB0LC_1LC1RB_0RD1LA_1RD1RB 4 10
             run_p_0RB0LC_1LC1RB_0RD1LA_1RD1RB (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
             ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LC_1LC1RB_0RD1LA_1RD1RB.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_0RB0LC_1LC1RB_0RD1LA_1RD1RB, cden, B0_0RB0LC_1LC1RB_0RD1LA_1RD1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_1LC1RB_0RD1LA_1RD1RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LC_1LC1RB_0RD1LA_1RD1RB
             = (StD, (rep [S1;S0] (S j) ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, B1_0RB0LC_1LC1RB_0RD1LA_1RD1RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LC_1LC1RB_0RD1LA_1RD1RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB0LC_1LC1RB_0RD1LA_1RD1RB. reflexivity.
Qed.

Lemma gsn_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S0;S1;S1]) [] i AI0_0RB0LC_1LC1RB_0RD1LA_1RD1RB.
