  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_0RD1LA_1RD1RB, cden, AI0_0RB0LC_1LC1RB_0RD1LA_1RD1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S0;S1;S1]) [] i AI1_0RB0LC_1LC1RB_0RD1LA_1RD1RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0LC_1LC1RB_0RD1LA_1RD1RB, cden, AI1_0RB0LC_1LC1RB_0RD1LA_1RD1RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ip q0 ++ [S0;S1;S1]) [] i AI1_0RB0LC_1LC1RB_0RD1LA_1RD1RB).
  split; [lia|]. split; [| exact (gen_0RB0LC_1LC1RB_0RD1LA_1RD1RB v i q0 E)].
  rewrite (gsn_0RB0LC_1LC1RB_0RD1LA_1RD1RB v i q0 E).
  exact (srun_sound tm false true chn_0RB0LC_1LC1RB_0RD1LA_1RD1RB AI0_0RB0LC_1LC1RB_0RD1LA_1RD1RB AI1_0RB0LC_1LC1RB_0RD1LA_1RD1RB 4 4
           run_inner_0RB0LC_1LC1RB_0RD1LA_1RD1RB (Ip q0 ++ [S0;S1;S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/0
    trailing blanks. *)
Lemma gbo_0RB0LC_1LC1RB_0RD1LA_1RD1RB : forall j, lift (cden [] [] j BB1_0RB0LC_1LC1RB_0RD1LA_1RD1RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_0RD1LA_1RD1RB = (StA, (rep [S1;S0] j ++ [S1;S0;S1;S1], S0, []))).
  { unfold cden, BB1_0RB0LC_1LC1RB_0RD1LA_1RD1RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
