(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_0RD1LD_0LA1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
