    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_0RD1LD_0LA1LA p j E)].
Qed.


(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LC_1LC1RB_0RD1LD_0LA1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LC_1LC1RB_0RD1LD_0LA1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LC_1LC1RB_0RD1LD_0LA1LA t p (pow2 j)).
  - exists (6 * j + 11), (cden [] [] j BB1_0RB0LC_1LC1RB_0RD1LD_0LA1LA). split;
      [| exact (gbo_0RB0LC_1LC1RB_0RD1LD_0LA1LA j)].
