    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_0RD1LD_0LA1LA B0_0RB0LC_1LC1RB_0RD1LD_0LA1LA BB1_0RB0LC_1LC1RB_0RD1LD_0LA1LA 6 11
             run_boot_0RB0LC_1LC1RB_0RD1LD_0LA1LA [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LC_1LC1RB_0RD1LD_0LA1LA xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LC_1LC1RB_0RD1LD_0LA1LA j)].
Qed.

