Lemma gsi_0RB0LC_1LC1RB_0RD1LD_1RB1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_110_111_111 q0 ++ [S0]) [] j A0_0RB0LC_1LC1RB_0RD1LD_1RB1LA.
