Definition AI0_0RB0LC_1LC1RB_0RD1LD_1RC1LA : sconf := mkC StD (mkS [] [S1;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB0LC_1LC1RB_0RD1LD_1RC1LA : sconf := mkC StD (mkS [] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chn_0RB0LC_1LC1RB_0RD1LD_1RC1LA : list lstep := [SRotL 1; SWin 2; SWinR 3; SCycL 3 0; SWin 4; SCycR 3; SWin 3; SUnrotL 1].

Lemma run_inner_0RB0LC_1LC1RB_0RD1LD_1RC1LA : srun tm false true chn_0RB0LC_1LC1RB_0RD1LD_1RC1LA AI0_0RB0LC_1LC1RB_0RD1LD_1RC1LA = Some (AI1_0RB0LC_1LC1RB_0RD1LD_1RC1LA, 6, 12).
