(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LC_1LC1RB_0RD1LD_1RC1LA : sconf := mkC StD (mkS [] [S1;S1;S1] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 []).
