(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j A0_0RB0LC_1LC1RB_1LA0LD_0RC0RB.
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p j q0 E) as (H1 & _).
  unfold Cc_0RB0LC_1LC1RB_1LA0LD_0RC0RB, cden, A0_0RB0LC_1LC1RB_1LA0LD_0RC0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S0] where the anchor has [] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_011_111_1 q0 ++ [S0]) [] j A1_0RB0LC_1LC1RB_1LA0LD_0RC0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (Alph_011_111_1.cview_some_Alph_011_111_1 p j q0 E) as (_ & H2).
  unfold Cc_0RB0LC_1LC1RB_1LA0LD_0RC0RB, cden, A1_0RB0LC_1LC1RB_1LA0LD_0RC0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S0]) with (([]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S0;S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

