  exact (srun_sound tm false true chi_0RB0LC_1LC1RB_1LA0LD_0RC0RB A0_0RB0LC_1LC1RB_1LA0LD_0RC0RB A1_0RB0LC_1LC1RB_1LA0LD_0RC0RB 8 6
