Lemma geo_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_1LC1RB_1LA0LD_0RC0RB) = lift (Cc (Pos.succ p)).
