  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_1LA0LD_0RC0RB = (StB, (rep [S0;S1;S1] j ++ [S1], S0, (([]) ++ [S0]) ++ [S0]))).
  { unfold cden, BB1_0RB0LC_1LC1RB_1LA0LD_0RC0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
