  unfold Cin_0RB0LC_1LC1RB_1LA0LD_0RC0RB, cden, BE0_0RB0LC_1LC1RB_1LA0LD_0RC0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB0LC_1LC1RB_1LA0LD_0RC0RB. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_1LA0LD_0RC0RB p (pow2 j)).
  - exists (8 * j + 7), (cden [] [] j BB1_0RB0LC_1LC1RB_1LA0LD_0RC0RB).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_1LA0LD_0RC0RB j)].
    rewrite (gso_0RB0LC_1LC1RB_1LA0LD_0RC0RB p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_1LA0LD_0RC0RB B0_0RB0LC_1LC1RB_1LA0LD_0RC0RB BB1_0RB0LC_1LC1RB_1LA0LD_0RC0RB 8 7
             run_boot_0RB0LC_1LC1RB_1LA0LD_0RC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (8 * j + 12), (cden [] [] j B1_0RB0LC_1LC1RB_1LA0LD_0RC0RB).
    split; [| exact (geo_0RB0LC_1LC1RB_1LA0LD_0RC0RB p j E)].
    rewrite (gxi_0RB0LC_1LC1RB_1LA0LD_0RC0RB j).
    exact (srun_sound tm true true che_0RB0LC_1LC1RB_1LA0LD_0RC0RB BE0_0RB0LC_1LC1RB_1LA0LD_0RC0RB B1_0RB0LC_1LC1RB_1LA0LD_0RC0RB 8 12
             run_exit_0RB0LC_1LC1RB_1LA0LD_0RC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_1LA0LD_0RC0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1LC1RB_1LA0LD_0RC0RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1LC1RB_1LA0LD_0RC0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 2.
  assert (H : match csteps tm 2 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 2 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1LC1RB_1LA0LD_0RC0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_1LA0LD_0RC0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_1LA0LD_0RC0RB p j E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
    [LapCertGlueLift.fire_via_int_lift] carries it to every anchor. *)
Lemma firei_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm false true l A0_0RB0LC_1LC1RB_1LA0LD_0RC0RB = Some t ->
  forall p j q0, cview p = (j, Some q0) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j q0 E.
  apply (fire_of_run_instr tm Cc false true l A0_0RB0LC_1LC1RB_1LA0LD_0RC0RB p j (Ap_Alph_011_111_1 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_0RB0LC_1LC1RB_1LA0LD_0RC0RB p j q0 E)].
Qed.

(** An instruction firing in the EXIT chain is reached from the outer overflow
    anchor by boot + the inner counter's own laps + that prefix. *)
Lemma firex_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l BE0_0RB0LC_1LC1RB_1LA0LD_0RC0RB = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k e, stepn tm k (lift (Cc p)) = Some e /\ instr_of e = t.
Proof.
  intros l t Hst p j E.
  apply (fire_via_fill tm Cc Cin lapin_0RB0LC_1LC1RB_1LA0LD_0RC0RB t p (pow2 j)).
  - exists (8 * j + 7), (cden [] [] j BB1_0RB0LC_1LC1RB_1LA0LD_0RC0RB). split;
      [| exact (gbo_0RB0LC_1LC1RB_1LA0LD_0RC0RB j)].
    rewrite (gso_0RB0LC_1LC1RB_1LA0LD_0RC0RB p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_1LA0LD_0RC0RB B0_0RB0LC_1LC1RB_1LA0LD_0RC0RB BB1_0RB0LC_1LC1RB_1LA0LD_0RC0RB 8 7
             run_boot_0RB0LC_1LC1RB_1LA0LD_0RC0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - apply (fire_lift_of_csteps tm (fun _ : positive => Cin (fill (pow2 j))) xH).
    apply (fire_of_run_instr tm (fun _ : positive => Cin (fill (pow2 j)))
                      true true l BE0_0RB0LC_1LC1RB_1LA0LD_0RC0RB xH j [] []);
      [exact Hst | reflexivity | reflexivity | exact (gxi_0RB0LC_1LC1RB_1LA0LD_0RC0RB j)].
Qed.

(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LC1RB_1LA0LD_0RC0RB : forall t, ~ In t pins_0RB0LC_1LC1RB_1LA0LD_0RC0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_0RB0LC_1LC1RB_1LA0LD_0RC0RB.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1LA0LD_0RC0RB [SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1: fires in the exit half of the overflow *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc lapil_0RB0LC_1LC1RB_1LA0LD_0RC0RB (StA, S1)).
    intros p1 j1 E1.
    exact (firex_0RB0LC_1LC1RB_1LA0LD_0RC0RB [SWinR 4; SCycL 3 0; SWin 1; SWinL 5; SCycR 5; SWin 1] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_0RB0LC_1LC1RB_1LA0LD_0RC0RB [SWinR 2; SRotL 1; SWin 1; SCycL 3 0; SWin 1] (StB, S0) ltac:(vm_compute; reflexivity)
