    Axiom footprint: [functional_extensionality_dep] (via [CTape.lift]). *)
Import Arith Lia Bool List PArith Wellfounded.
Import BBB4_Statement CTape Mirror.
Import FunctionalExtensionality.
Import WTape LapGlue LapGlueQH LapGlueAbs
                                  MonoCounter JpCounter ILCounter LapCertGlue LapCertGlueLift IXPGadgets NestedLap NestedLapLift.
Import TNF_QH.
Import LapDecider.
Import BBBT4_Statement.
Import WrapTr.
Import AnchorVisitsTr.
Import LapGlueTr.
Import TNF_QHTr.
Import ListNotations.

Definition mk_0RB0LC_1LC1RB_1LA0RD_0LA1RC (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB0LC_1LC1RB_1LA0RD_0LA1RC.

(** 0RB0LC_1LC1RB_1LA0RD_0LA1RC *)
(** 0RB0LC_1LC1RB_1LA0RD_0LA1RC -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LC_1LC1RB_1LA0RD_0LA1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DL StA | StC, S1 => mk S0 DR StD
  | StD, S0 => mk S0 DL StA | StD, S1 => mk S1 DR StC end.

(** Its mirror 0LB0RC_1RC1LB_1RA0LD_0RA1LC: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC1RB_1LA0RD_0LA1RC : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DR StA | StC, S1 => mk S0 DL StD
  | StD, S0 => mk S0 DR StA | StD, S1 => mk S1 DL StC end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC1RB_1LA0RD_0LA1RC : list Instr := [].
Definition tmw_0RB0LC_1LC1RB_1LA0RD_0LA1RC : TM := tm_wrap_trs tmm_0RB0LC_1LC1RB_1LA0RD_0LA1RC pins_0RB0LC_1LC1RB_1LA0RD_0LA1RC.
Local Notation tm := tmw_0RB0LC_1LC1RB_1LA0RD_0LA1RC.

Lemma mirror_ok_0RB0LC_1LC1RB_1LA0RD_0LA1RC : mirror_tm tm_0RB0LC_1LC1RB_1LA0RD_0LA1RC = tmm_0RB0LC_1LC1RB_1LA0RD_0LA1RC.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB0LC_1LC1RB_1LA0RD_0LA1RC (p : positive) : cconf := (StB, (Ip p ++ [S0], S0, [S1])).
Local Notation Cc := Cc_0RB0LC_1LC1RB_1LA0RD_0LA1RC.

(** ** The certificate *)

Definition A0_0RB0LC_1LC1RB_1LA0RD_0LA1RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition A1_0RB0LC_1LC1RB_1LA0RD_0LA1RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chi_0RB0LC_1LC1RB_1LA0RD_0LA1RC : list lstep := [SWin 2; SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 3].

Lemma run_int_0RB0LC_1LC1RB_1LA0RD_0LA1RC : srun tm false true chi_0RB0LC_1LC1RB_1LA0RD_0LA1RC A0_0RB0LC_1LC1RB_1LA0RD_0LA1RC = Some (A1_0RB0LC_1LC1RB_1LA0RD_0LA1RC, 4, 12).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB0LC_1LC1RB_1LA0RD_0LA1RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition B1_0RB0LC_1LC1RB_1LA0RD_0LA1RC : sconf := mkC StB (mkS [] [S1;S0] 1 1 [S1]) S0 (mkS [S1;S0] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StB *)
Definition Cin_0RB0LC_1LC1RB_1LA0RD_0LA1RC (v : positive) : cconf := (StB, (Ip v ++ [S1], S0, [S1])).
Local Notation Cin := Cin_0RB0LC_1LC1RB_1LA0RD_0LA1RC.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0LC_1LC1RB_1LA0RD_0LA1RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [S1] [] 0 0 []).
Definition AI1_0RB0LC_1LC1RB_1LA0RD_0LA1RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chn_0RB0LC_1LC1RB_1LA0RD_0LA1RC : list lstep := [SWin 2; SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 3].

Lemma run_inner_0RB0LC_1LC1RB_1LA0RD_0LA1RC : srun tm false true chn_0RB0LC_1LC1RB_1LA0RD_0LA1RC AI0_0RB0LC_1LC1RB_1LA0RD_0LA1RC = Some (AI1_0RB0LC_1LC1RB_1LA0RD_0LA1RC, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0LC_1LC1RB_1LA0RD_0LA1RC : sconf := mkC StB (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S1;S0] [] 0 0 []).
Definition chb_0RB0LC_1LC1RB_1LA0RD_0LA1RC : list lstep := [SWin 2; SCycL 2 0; SWin 6; SCycR 2; SWin 1; SWinR 3].

Lemma run_boot_0RB0LC_1LC1RB_1LA0RD_0LA1RC : srun tm true true chb_0RB0LC_1LC1RB_1LA0RD_0LA1RC B0_0RB0LC_1LC1RB_1LA0RD_0LA1RC = Some (BB1_0RB0LC_1LC1RB_1LA0RD_0LA1RC, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LC_1LC1RB_1LA0RD_0LA1RC : sconf := mkC StB (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S1] [] 0 0 []).
Definition che_0RB0LC_1LC1RB_1LA0RD_0LA1RC : list lstep := [SWin 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 1; SWinR 3; SRotL 2; SFoldL 1].

Lemma run_exit_0RB0LC_1LC1RB_1LA0RD_0LA1RC : srun tm true true che_0RB0LC_1LC1RB_1LA0RD_0LA1RC BE0_0RB0LC_1LC1RB_1LA0RD_0LA1RC = Some (B1_0RB0LC_1LC1RB_1LA0RD_0LA1RC, 4, 12).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Ip q0 ++ [S0]) [] j A0_0RB0LC_1LC1RB_1LA0RD_0LA1RC.
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (H1 & _).
  unfold Cc_0RB0LC_1LC1RB_1LA0RD_0LA1RC, cden, A0_0RB0LC_1LC1RB_1LA0RD_0LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

(** The lap ends on [S1;S0] where the anchor has [S1] -- one trailing blank,
    which [lift] cannot see. *)
Lemma gei_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ip q0 ++ [S0]) [] j A1_0RB0LC_1LC1RB_1LA0RD_0LA1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct (ILCounter.cview_some_I p j q0 E) as (_ & H2).
  unfold Cc_0RB0LC_1LC1RB_1LA0RD_0LA1RC, cden, A1_0RB0LC_1LC1RB_1LA0RD_0LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S0]) with (([S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof.
  intros p j q0 E.
  exists (4 * j + 12), (cden (Ip q0 ++ [S0]) [] j A1_0RB0LC_1LC1RB_1LA0RD_0LA1RC).
  split; [lia|]. split; [| exact (gei_0RB0LC_1LC1RB_1LA0RD_0LA1RC p j q0 E)].
  rewrite (gsi_0RB0LC_1LC1RB_1LA0RD_0LA1RC p j q0 E).
  exact (srun_sound tm false true chi_0RB0LC_1LC1RB_1LA0RD_0LA1RC A0_0RB0LC_1LC1RB_1LA0RD_0LA1RC A1_0RB0LC_1LC1RB_1LA0RD_0LA1RC 4 12
           run_int_0RB0LC_1LC1RB_1LA0RD_0LA1RC (Ip q0 ++ [S0]) [] j
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

Lemma gso_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LC_1LC1RB_1LA0RD_0LA1RC.
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (H1 & _).
  unfold Cc_0RB0LC_1LC1RB_1LA0RD_0LA1RC, cden, B0_0RB0LC_1LC1RB_1LA0RD_0LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_1LC1RB_1LA0RD_0LA1RC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (ILCounter.cview_none_I p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LC_1LC1RB_1LA0RD_0LA1RC
             = (StB, (rep [S1;S0] (S j) ++ [S1], S0, ([S1]) ++ [S0]))).
  { unfold cden, B1_0RB0LC_1LC1RB_1LA0RD_0LA1RC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StB, ((rep [S1;S0] (S j) ++ [S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_0RB0LC_1LC1RB_1LA0RD_0LA1RC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lift_app_blank. rewrite !lbl_0RB0LC_1LC1RB_1LA0RD_0LA1RC. reflexivity.
Qed.

Lemma gsn_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_0RB0LC_1LC1RB_1LA0RD_0LA1RC.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_1LA0RD_0LA1RC, cden, AI0_0RB0LC_1LC1RB_1LA0RD_0LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LC_1LC1RB_1LA0RD_0LA1RC) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0LC_1LC1RB_1LA0RD_0LA1RC, cden, AI1_0RB0LC_1LC1RB_1LA0RD_0LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  change ([S1;S0]) with (([S1]) ++ [S0]).
  rewrite !lift_app_blank.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 12), (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LC_1LC1RB_1LA0RD_0LA1RC).
  split; [lia|]. split; [| exact (gen_0RB0LC_1LC1RB_1LA0RD_0LA1RC v i q0 E)].
  rewrite (gsn_0RB0LC_1LC1RB_1LA0RD_0LA1RC v i q0 E).
  exact (srun_sound tm false true chn_0RB0LC_1LC1RB_1LA0RD_0LA1RC AI0_0RB0LC_1LC1RB_1LA0RD_0LA1RC AI1_0RB0LC_1LC1RB_1LA0RD_0LA1RC 4 12
           run_inner_0RB0LC_1LC1RB_1LA0RD_0LA1RC (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall j, lift (cden [] [] j BB1_0RB0LC_1LC1RB_1LA0RD_0LA1RC) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_1LA0RD_0LA1RC = (StB, (rep [S1;S0] j ++ [S1;S1], S0, ([S1]) ++ [S0]))).
  { unfold cden, BB1_0RB0LC_1LC1RB_1LA0RD_0LA1RC, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StB, (rep [S1;S0] j ++ [S1;S1], S0, [S1]))).
  { unfold Cin_0RB0LC_1LC1RB_1LA0RD_0LA1RC. rewrite epow2_0RB0LC_1LC1RB_1LA0RD_0LA1RC.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LC_1LC1RB_1LA0RD_0LA1RC. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LC_1LC1RB_1LA0RD_0LA1RC.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_1LA0RD_0LA1RC, cden, BE0_0RB0LC_1LC1RB_1LA0RD_0LA1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. exact lapi_0RB0LC_1LC1RB_1LA0RD_0LA1RC. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_1LA0RD_0LA1RC p (pow2 j)).
  - exists (4 * j + 12), (cden [] [] j BB1_0RB0LC_1LC1RB_1LA0RD_0LA1RC).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_1LA0RD_0LA1RC j)].
    rewrite (gso_0RB0LC_1LC1RB_1LA0RD_0LA1RC p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_1LA0RD_0LA1RC B0_0RB0LC_1LC1RB_1LA0RD_0LA1RC BB1_0RB0LC_1LC1RB_1LA0RD_0LA1RC 4 12
             run_boot_0RB0LC_1LC1RB_1LA0RD_0LA1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 12), (cden [] [] j B1_0RB0LC_1LC1RB_1LA0RD_0LA1RC).
    split; [| exact (geo_0RB0LC_1LC1RB_1LA0RD_0LA1RC p j E)].
    rewrite (gxi_0RB0LC_1LC1RB_1LA0RD_0LA1RC j).
    exact (srun_sound tm true true che_0RB0LC_1LC1RB_1LA0RD_0LA1RC BE0_0RB0LC_1LC1RB_1LA0RD_0LA1RC B1_0RB0LC_1LC1RB_1LA0RD_0LA1RC 4 12
             run_exit_0RB0LC_1LC1RB_1LA0RD_0LA1RC [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_1LA0RD_0LA1RC p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_0RB0LC_1LC1RB_1LA0RD_0LA1RC p j' E).
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1LC1RB_1LA0RD_0LA1RC : exists t0, stepn tm t0 InitES = Some (lift (Cc 2)).
Proof.
  exists 16.
  assert (H : match csteps tm 16 c0 with
              | Some c => ceqb c (Cc 2) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tm 16 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_0RB0LC_1LC1RB_1LA0RD_0LA1RC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_0RB0LC_1LC1RB_1LA0RD_0LA1RC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_1LA0RD_0LA1RC p j [] []);
