Definition mk_0RB0LC_1LC1RB_1LD1LA_0RD0RB (w : Sym) (d : Dir) (n : St) : option Trans := Some (mkTrans w d n).
Local Notation mk := mk_0RB0LC_1LC1RB_1LD1LA_0RD0RB.

(** 0RB0LC_1LC1RB_1LD1LA_0RD0RB *)
(** 0RB0LC_1LC1RB_1LD1LA_0RD0RB -- the real machine (its counter grows RIGHT). *)
Definition tm_0RB0LC_1LC1RB_1LD1LA_0RD0RB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DR StB | StA, S1 => mk S0 DL StC
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S1 DR StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DL StA
  | StD, S0 => mk S0 DR StD | StD, S1 => mk S0 DR StB end.

(** Its mirror 0LB0RC_1RC1LB_1RD1RA_0LD0LB: the same counter grown leftward.  Every
    lemma below runs on the MIRRORED table;
    [Mirror.mirror_never_qh] transfers the conclusion back. *)
Definition tmm_0RB0LC_1LC1RB_1LD1LA_0RD0RB : TM := fun q s => match q, s with
  | StA, S0 => mk S0 DL StB | StA, S1 => mk S0 DR StC
  | StB, S0 => mk S1 DR StC | StB, S1 => mk S1 DL StB
  | StC, S0 => mk S1 DR StD | StC, S1 => mk S1 DR StA
  | StD, S0 => mk S0 DL StD | StD, S1 => mk S0 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_0RB0LC_1LC1RB_1LD1LA_0RD0RB : list Instr := [].
Definition tmw_0RB0LC_1LC1RB_1LD1LA_0RD0RB : TM := tm_wrap_trs tmm_0RB0LC_1LC1RB_1LD1LA_0RD0RB pins_0RB0LC_1LC1RB_1LD1LA_0RD0RB.
Local Notation tm := tmw_0RB0LC_1LC1RB_1LD1LA_0RD0RB.

Lemma mirror_ok_0RB0LC_1LC1RB_1LD1LA_0RD0RB : mirror_tm tm_0RB0LC_1LC1RB_1LD1LA_0RD0RB = tmm_0RB0LC_1LC1RB_1LD1LA_0RD0RB.
Proof.
  apply functional_extensionality; intro q;
    apply functional_extensionality; intro b; destruct q, b; reflexivity.
Qed.

Definition Cc_0RB0LC_1LC1RB_1LD1LA_0RD0RB (p : positive) : cconf := (StD, (Ap_Alph_10_11_11 p ++ [S0], S0, [])).
Local Notation Cc := Cc_0RB0LC_1LC1RB_1LD1LA_0RD0RB.

(** ** The certificate *)

(** j = 0: the repeated block is absent, so the whole lap is concrete. *)
Definition Z0_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StD (mkS [S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition Z1_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StD (mkS [S1;S1] [] 0 0 []) S0 (mkS [] [] 0 0 []).
Definition chz_0RB0LC_1LC1RB_1LD1LA_0RD0RB : list lstep := [SWin 4].

Lemma run_z_0RB0LC_1LC1RB_1LD1LA_0RD0RB : srun tm false true chz_0RB0LC_1LC1RB_1LD1LA_0RD0RB Z0_0RB0LC_1LC1RB_1LD1LA_0RD0RB = Some (Z1_0RB0LC_1LC1RB_1LD1LA_0RD0RB, 0, 4).
Proof. vm_compute. reflexivity. Qed.

(** j = S j': one copy of the unit sits in the PREFIX, so the head always has
    a concrete cell to step onto. *)
Definition P0_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StD (mkS [S1;S1] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition P1_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StD (mkS [S1;S0] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chp_0RB0LC_1LC1RB_1LD1LA_0RD0RB : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_p_0RB0LC_1LC1RB_1LD1LA_0RD0RB : srun tm false true chp_0RB0LC_1LC1RB_1LD1LA_0RD0RB P0_0RB0LC_1LC1RB_1LD1LA_0RD0RB = Some (P1_0RB0LC_1LC1RB_1LD1LA_0RD0RB, 4, 8).
Proof. vm_compute. reflexivity. Qed.

Definition B0_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StD (mkS [] [S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []).
Definition B1_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StD (mkS [] [S1;S0] 1 1 [S1;S1]) S0 (mkS [] [] 0 0 []).
(** ** The INNER anchor family -- Ip at StA *)
Definition Cin_0RB0LC_1LC1RB_1LD1LA_0RD0RB (v : positive) : cconf := (StA, (Ip v ++ [S1], S0, [])).
Local Notation Cin := Cin_0RB0LC_1LC1RB_1LD1LA_0RD0RB.

(** [E (2^n) = A^n C]: the value this family's count starts at. *)
Lemma epow2_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall n, Ip (pow2 n) = rep [S1;S0] n ++ [S1].
Proof. induction n; simpl; [reflexivity | rewrite IHn; reflexivity]. Qed.

(** Its own INTERIOR lap -- ordinary and affine.  Iterating it to the fill is
    where a [Theta(2^j)] lives, and [inner_to_fill_lift] keeps it inside an
    existential. *)
Definition AI0_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S0]) S0 (mkS [] [] 0 0 []).
Definition AI1_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition chn_0RB0LC_1LC1RB_1LD1LA_0RD0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_inner_0RB0LC_1LC1RB_1LD1LA_0RD0RB : srun tm false true chn_0RB0LC_1LC1RB_1LD1LA_0RD0RB AI0_0RB0LC_1LC1RB_1LD1LA_0RD0RB = Some (AI1_0RB0LC_1LC1RB_1LD1LA_0RD0RB, 4, 4).
Proof. vm_compute. reflexivity. Qed.

(** *** boot: the outer overflow anchor -> the first inner anchor at [pow2 j] *)
Definition BB1_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StA (mkS [] [S1;S0] 1 0 [S1;S1]) S0 (mkS [S0] [] 0 0 []).
Definition chb_0RB0LC_1LC1RB_1LD1LA_0RD0RB : list lstep := [SRotL 1; SWin 1; SRotL 1; SWin 1; SCycL 2 0; SWin 2; SCycR 2; SWin 1; SUnrotL 1].

Lemma run_boot_0RB0LC_1LC1RB_1LD1LA_0RD0RB : srun tm true true chb_0RB0LC_1LC1RB_1LD1LA_0RD0RB B0_0RB0LC_1LC1RB_1LD1LA_0RD0RB = Some (BB1_0RB0LC_1LC1RB_1LD1LA_0RD0RB, 4, 5).
Proof. vm_compute. reflexivity. Qed.

(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_0RB0LC_1LC1RB_1LD1LA_0RD0RB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [] [] 0 0 []).
Definition che_0RB0LC_1LC1RB_1LD1LA_0RD0RB : list lstep := [SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 1; SWinR 1; SFoldL 1].

Lemma run_exit_0RB0LC_1LC1RB_1LD1LA_0RD0RB : srun tm true true che_0RB0LC_1LC1RB_1LD1LA_0RD0RB BE0_0RB0LC_1LC1RB_1LD1LA_0RD0RB = Some (B1_0RB0LC_1LC1RB_1LD1LA_0RD0RB, 4, 7).
Proof. vm_compute. reflexivity. Qed.

(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z0_0RB0LC_1LC1RB_1LD1LA_0RD0RB /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0 Z1_0RB0LC_1LC1RB_1LD1LA_0RD0RB = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p 0 q0 E) as (H1 & H2).
  unfold Cc_0RB0LC_1LC1RB_1LD1LA_0RD0RB, cden, Z0_0RB0LC_1LC1RB_1LD1LA_0RD0RB, Z1_0RB0LC_1LC1RB_1LD1LA_0RD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P0_0RB0LC_1LC1RB_1LD1LA_0RD0RB /\
  cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j P1_0RB0LC_1LC1RB_1LD1LA_0RD0RB = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_10_11_11.cview_some_Alph_10_11_11 p (S j) q0 E) as (H1 & H2).
  unfold Cc_0RB0LC_1LC1RB_1LD1LA_0RD0RB, cden, P0_0RB0LC_1LC1RB_1LD1LA_0RD0RB, P1_0RB0LC_1LC1RB_1LD1LA_0RD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_0RB0LC_1LC1RB_1LD1LA_0RD0RB p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_0RB0LC_1LC1RB_1LD1LA_0RD0RB Z0_0RB0LC_1LC1RB_1LD1LA_0RD0RB Z1_0RB0LC_1LC1RB_1LD1LA_0RD0RB 0 4
               run_z_0RB0LC_1LC1RB_1LD1LA_0RD0RB (Ap_Alph_10_11_11 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_0RB0LC_1LC1RB_1LD1LA_0RD0RB p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_0RB0LC_1LC1RB_1LD1LA_0RD0RB P0_0RB0LC_1LC1RB_1LD1LA_0RD0RB P1_0RB0LC_1LC1RB_1LD1LA_0RD0RB 4 8
               run_p_0RB0LC_1LC1RB_1LD1LA_0RD0RB (Ap_Alph_10_11_11 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_0RB0LC_1LC1RB_1LD1LA_0RD0RB.
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (H1 & _).
  unfold Cc_0RB0LC_1LC1RB_1LD1LA_0RD0RB, cden, B0_0RB0LC_1LC1RB_1LD1LA_0RD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_1LC1RB_1LD1LA_0RD0RB) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_10_11_11.cview_none_Alph_10_11_11 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_0RB0LC_1LC1RB_1LD1LA_0RD0RB
             = (StD, (rep [S1;S0] (S j) ++ [S1;S1], S0, []))).
  { unfold cden, B1_0RB0LC_1LC1RB_1LD1LA_0RD0RB, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StD, ((rep [S1;S0] (S j) ++ [S1;S1]) ++ [S0], S0, []))).
  { unfold Cc_0RB0LC_1LC1RB_1LD1LA_0RD0RB. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_0RB0LC_1LC1RB_1LD1LA_0RD0RB. reflexivity.
Qed.

Lemma gsn_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall v i q0, cview v = (i, Some q0) ->
  Cin v = cden (Ip q0 ++ [S1]) [] i AI0_0RB0LC_1LC1RB_1LD1LA_0RD0RB.
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_1LD1LA_0RD0RB, cden, AI0_0RB0LC_1LC1RB_1LD1LA_0RD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gen_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LC_1LC1RB_1LD1LA_0RD0RB) = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E. destruct (ILCounter.cview_some_I v i q0 E) as (_ & H2).
  unfold Cin_0RB0LC_1LC1RB_1LD1LA_0RD0RB, cden, AI1_0RB0LC_1LC1RB_1LD1LA_0RD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * i + 0) with i by lia.
  replace (0 * i + 0) with 0 by lia.
  cbn [rep app]. rewrite ?app_nil_r.
  rewrite H2. first [ rewrite <- (app_assoc (rep [S1;S0] i)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapin_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall v i q0, cview v = (i, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cin v) = Some c'
               /\ lift c' = lift (Cin (Pos.succ v)).
Proof.
  intros v i q0 E.
  exists (4 * i + 4), (cden (Ip q0 ++ [S1]) [] i AI1_0RB0LC_1LC1RB_1LD1LA_0RD0RB).
  split; [lia|]. split; [| exact (gen_0RB0LC_1LC1RB_1LD1LA_0RD0RB v i q0 E)].
  rewrite (gsn_0RB0LC_1LC1RB_1LD1LA_0RD0RB v i q0 E).
  exact (srun_sound tm false true chn_0RB0LC_1LC1RB_1LD1LA_0RD0RB AI0_0RB0LC_1LC1RB_1LD1LA_0RD0RB AI1_0RB0LC_1LC1RB_1LD1LA_0RD0RB 4 4
           run_inner_0RB0LC_1LC1RB_1LD1LA_0RD0RB (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
Qed.

(** The chain into this family lands on its anchor up to 0/1
    trailing blanks. *)
Lemma gbo_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall j, lift (cden [] [] j BB1_0RB0LC_1LC1RB_1LD1LA_0RD0RB) = lift (Cin (pow2 j)).
Proof.
  intro j.
  assert (HD : cden [] [] j BB1_0RB0LC_1LC1RB_1LD1LA_0RD0RB = (StA, (rep [S1;S0] j ++ [S1;S1], S0, ([]) ++ [S0]))).
  { unfold cden, BB1_0RB0LC_1LC1RB_1LD1LA_0RD0RB, sden;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 0) with j by lia.
    cbn [rep app]. rewrite <- ?app_assoc. cbn [app]. rewrite ?app_nil_r.
    reflexivity. }
  assert (HC : Cin (pow2 j) = (StA, (rep [S1;S0] j ++ [S1;S1], S0, []))).
  { unfold Cin_0RB0LC_1LC1RB_1LD1LA_0RD0RB. rewrite epow2_0RB0LC_1LC1RB_1LD1LA_0RD0RB.
    first [ rewrite <- app_assoc; reflexivity
          | rewrite ?app_nil_r; reflexivity
          | cbn [app]; rewrite <- ?app_assoc; cbn [app];
            rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite ?lbl_0RB0LC_1LC1RB_1LD1LA_0RD0RB. rewrite ?lift_app_blank. reflexivity.
Qed.

(** This family's all-ones fill IS the next chain's start.  [cview (fill
    (pow2 j)) = (S j, None)] ([NestedLapLift.cview_fill_pow2]), so the
    family's own overflow decomposition names the word. *)
Lemma gxi_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_0RB0LC_1LC1RB_1LD1LA_0RD0RB.
Proof.
  intro j.
  destruct (ILCounter.cview_none_I (fill (pow2 j)) j (cview_fill_pow2 j)) as (H1 & _).
  unfold Cin_0RB0LC_1LC1RB_1LD1LA_0RD0RB, cden, BE0_0RB0LC_1LC1RB_1LD1LA_0RD0RB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  replace (0 * j + 0) with 0 by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- ?app_assoc; cbn [app];
        rewrite ?app_nil_r; reflexivity | reflexivity ].
Qed.

(** The interior lap, restated up to [lift] -- what [vis_via_ovf_lift] and
    [vis_via_fill] consume. *)
Lemma lapil_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall p j q0, cview p = (j, Some q0) ->
  exists n c', 0 < n /\ csteps tm n (Cc p) = Some c'
               /\ lift c' = lift (Cc (Pos.succ p)).
Proof. intros p j q0 E. destruct (lapi_0RB0LC_1LC1RB_1LD1LA_0RD0RB p j q0 E) as (n & Hn & Hr).
  exists n, (Cc (Pos.succ p)).
  split; [exact Hn | split; [exact Hr | reflexivity]]. Qed.

(** The outer OVERFLOW branch, composed.  The exponential cost is the
    [exists n] inside [inner_to_fill_lift]; no formula for it is ever
    written. *)
Lemma lapo_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall p j, cview p = (S j, None) ->
  exists n c', csteps tm n (Cc p) = Some c'
          /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intros p j E.
  apply (nested_overflow_lift tm Cc Cin lapin_0RB0LC_1LC1RB_1LD1LA_0RD0RB p (pow2 j)).
  - exists (4 * j + 5), (cden [] [] j BB1_0RB0LC_1LC1RB_1LD1LA_0RD0RB).
    split; [lia|]. split; [| exact (gbo_0RB0LC_1LC1RB_1LD1LA_0RD0RB j)].
    rewrite (gso_0RB0LC_1LC1RB_1LD1LA_0RD0RB p j E).
    exact (srun_sound tm true true chb_0RB0LC_1LC1RB_1LD1LA_0RD0RB B0_0RB0LC_1LC1RB_1LD1LA_0RD0RB BB1_0RB0LC_1LC1RB_1LD1LA_0RD0RB 4 5
             run_boot_0RB0LC_1LC1RB_1LD1LA_0RD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 7), (cden [] [] j B1_0RB0LC_1LC1RB_1LD1LA_0RD0RB).
    split; [| exact (geo_0RB0LC_1LC1RB_1LD1LA_0RD0RB p j E)].
    rewrite (gxi_0RB0LC_1LC1RB_1LD1LA_0RD0RB j).
    exact (srun_sound tm true true che_0RB0LC_1LC1RB_1LD1LA_0RD0RB BE0_0RB0LC_1LC1RB_1LD1LA_0RD0RB B1_0RB0LC_1LC1RB_1LD1LA_0RD0RB 4 7
             run_exit_0RB0LC_1LC1RB_1LD1LA_0RD0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
Qed.



(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_1LD1LA_0RD0RB : forall p, exists n c',
