Lemma geo_0RB0LC_1LC1RB_1LD1LA_0RD1RB : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_0RB0LC_1LC1RB_1LD1LA_0RD1RB) = lift (Cc (Pos.succ p)).
