Lemma gei_0RB0LC_1LC1RB_1LD1LA_1RD0RB : forall p j q0, cview p = (j, Some q0) ->
  lift (cden (Ap_Alph_10_11_11 q0 ++ [S0]) [] j A1_0RB0LC_1LC1RB_1LD1LA_1RD0RB) = lift (Cc (Pos.succ p)).
Proof.
