(** ** The lap *)

Lemma lap_0RB0LC_1LC1RB_1LD1LA_1RD0RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_0RB0LC_1LC1RB_1LD1LA_1RD0RB p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_0RB0LC_1LC1RB_1LD1LA_1RD0RB B0_0RB0LC_1LC1RB_1LD1LA_1RD0RB B1_0RB0LC_1LC1RB_1LD1LA_1RD0RB 4 31 p j' [] []).
    + exact run_ovf_0RB0LC_1LC1RB_1LD1LA_1RD0RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_0RB0LC_1LC1RB_1LD1LA_1RD0RB p j' E).
    + exact (geo_0RB0LC_1LC1RB_1LD1LA_1RD0RB p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma boot_0RB0LC_1LC1RB_1LD1LA_1RD0RB : exists t0, stepn tm t0 InitES = Some (lift (Cc 1)).
Proof.
  exists 38.
  assert (H : match csteps tm 38 c0 with
