  apply (fire_of_run_instr tm Cc true true l B0_0RB0LC_1LC1RB_1LD1LA_1RD0RB p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_0RB0LC_1LC1RB_1LD1LA_1RD0RB p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_0RB0LC_1LC1RB_1LD1LA_1RD0RB : forall t, ~ In t pins_0RB0LC_1LC1RB_1LD1LA_1RD0RB ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
